CREATE TABLE `education_history` (
  `edu_id` int(11) NOT NULL,
  `std_id` int(11) NOT NULL COMMENT 'รหัสนักศึกษา (Refer to student table)',
  `degree_level` varchar(50) DEFAULT NULL COMMENT 'ระดับวุฒิ (Bachelor, Master, Doctoral)',
  `degree_name` varchar(255) DEFAULT NULL COMMENT 'ชื่อวุฒิ (e.g., B.Sc. Computer Science)',
