CREATE TABLE `english_score` (
  `es_id` int(11) NOT NULL,
  `std_id` int(11) NOT NULL COMMENT 'รหัสนักศึกษา',
  `test_type` varchar(50) DEFAULT NULL COMMENT 'ประเภทสอบ: IELTS, TOEFL-iBT, MU GRAD Plus, MU ELT',
  `submission_type` enum('entrance','graduation','other') DEFAULT 'entrance' COMMENT 'ประเภทการยื่น: entrance=ยื่นเข้า, graduation=ยื่นจบ',
  `exam_date` date DEFAULT NULL COMMENT 'วันที่สอบ',
  `score_total` decimal(5,2) DEFAULT NULL COMMENT 'คะแนนรวม',
  `score_listen` decimal(5,2) DEFAULT NULL COMMENT 'คะแนนฟัง',
  `score_speak` decimal(5,2) DEFAULT NULL COMMENT 'คะแนนพูด',
  `score_read` decimal(5,2) DEFAULT NULL COMMENT 'คะแนนอ่าน',
  `score_write` decimal(5,2) DEFAULT NULL COMMENT 'คะแนนเขียน',
  `remark` text DEFAULT NULL COMMENT 'หมายเหตุ',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

