--
-- Table structure for table `enrollment`
--

CREATE TABLE `enrollment` (
  `enrollment_id` int(11) NOT NULL,
  `offering_id` int(11) NOT NULL COMMENT 'รหัสการเปิดสอน (เชื่อมกับ course_offering)',
  `std_id` int(11) NOT NULL COMMENT 'รหัสนักศึกษา (เชื่อมกับ student)',
  `enrollment_date` date DEFAULT NULL COMMENT 'วันที่ลงทะเบียน',
  `status` enum('enrolled','dropped','completed','withdrawn') DEFAULT 'enrolled' COMMENT 'สถานะการลงทะเบียน',
  `grade` varchar(5) DEFAULT NULL COMMENT 'เกรดที่ได้ (A, B+, etc.)',
  `grade_point` decimal(3,2) DEFAULT NULL COMMENT 'แต้มระดับคะแนน (4.00, 3.50)',
  `attendance_percent` decimal(5,2) DEFAULT NULL COMMENT 'เปอร์เซ็นต์การเข้าเรียน',
  `midterm_score` decimal(5,2) DEFAULT NULL COMMENT 'คะแนนสอบกลางภาค',
  `final_score` decimal(5,2) DEFAULT NULL COMMENT 'คะแนนสอบปลายภาค',
  `total_score` decimal(5,2) DEFAULT NULL COMMENT 'คะแนนรวม',
  `remarks` text DEFAULT NULL COMMENT 'หมายเหตุ',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

