--
-- Triggers `enrollment`
--
DELIMITER $$
CREATE TRIGGER `after_enrollment_delete` AFTER DELETE ON `enrollment` FOR EACH ROW BEGIN
    UPDATE `course_offering` 
    SET `current_enrolled` = (
        SELECT COUNT(*) 
        FROM `enrollment` 
        WHERE `offering_id` = OLD.offering_id 
        AND `status` = 'enrolled'
    )
    WHERE `offering_id` = OLD.offering_id;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `after_enrollment_insert` AFTER INSERT ON `enrollment` FOR EACH ROW BEGIN
    -- อัปเดตยอดรวมในตาราง course_offering เฉพาะคนที่มีสถานะ enrolled
    UPDATE `course_offering` 
    SET `current_enrolled` = (
        SELECT COUNT(*) 
        FROM `enrollment` 
        WHERE `offering_id` = NEW.offering_id 
        AND `status` = 'enrolled'
    )
    WHERE `offering_id` = NEW.offering_id;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `after_enrollment_update` AFTER UPDATE ON `enrollment` FOR EACH ROW BEGIN
    -- ถ้ามีการเปลี่ยนวิชาที่ลง หรือเปลี่ยนสถานะ ให้คำนวณใหม่ทั้งวิชาเก่าและวิชาใหม่
    IF (OLD.offering_id <> NEW.offering_id OR OLD.status <> NEW.status) THEN
        -- อัปเดตวิชาเก่า
        UPDATE `course_offering` 
        SET `current_enrolled` = (
            SELECT COUNT(*) 
            FROM `enrollment` 
            WHERE `offering_id` = OLD.offering_id 
            AND `status` = 'enrolled'
        )
        WHERE `offering_id` = OLD.offering_id;
        
        -- อัปเดตวิชาใหม่
        UPDATE `course_offering` 
        SET `current_enrolled` = (
            SELECT COUNT(*) 
            FROM `enrollment` 
            WHERE `offering_id` = NEW.offering_id 
            AND `status` = 'enrolled'
        )
        WHERE `offering_id` = NEW.offering_id;
    END IF;
END
$$
DELIMITER ;

