--
-- Table structure for table `graduation`
--

CREATE TABLE `graduation` (
  `grad_id` int(11) NOT NULL,
  `std_id` int(11) NOT NULL COMMENT 'FK → student.std_id',
  `grad_date` date DEFAULT NULL COMMENT 'วันที่สำเร็จการศึกษา (Graduation Date)',
  `council_date` date DEFAULT NULL COMMENT 'วันสภาที่อนุมัติ (Council Approval Date)',
  `council_academic_year` varchar(20) DEFAULT NULL COMMENT 'ปีการศึกษาที่สภาอนุมัติปริญญา (e.g., 2567/1)',
  `grad_status` enum('pending','approved','cancelled') NOT NULL DEFAULT 'pending' COMMENT 'pending=รอดำเนินการ, approved=อนุมัติแล้ว, cancelled=ยกเลิก',
  `notes` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Graduation records – stores date, council approval, and academic year';

