CREATE TABLE `personal` (
  `mpd_id` int(11) NOT NULL COMMENT 'รหัสอ้างอิงบุคลากร (Master Personnel Database ID)',
  `invid` int(4) DEFAULT NULL COMMENT 'รหัส Investigator ID',
  `staff_id` varchar(10) DEFAULT NULL COMMENT 'รหัสพนักงาน',
  `title_id` int(11) DEFAULT NULL COMMENT 'รหัสคำนำหน้าชื่อ',
  `eng_name` varchar(100) DEFAULT NULL COMMENT 'ชื่อ (อังกฤษ)',
  `eng_mname` varchar(100) DEFAULT NULL COMMENT 'ชื่อกลาง (อังกฤษ)',
  `eng_surname` varchar(100) DEFAULT NULL COMMENT 'นามสกุล (อังกฤษ)',
  `th_name` varchar(100) DEFAULT NULL COMMENT 'ชื่อ (ไทย)',
  `th_mname` varchar(100) DEFAULT NULL COMMENT 'ชื่อกลาง (ไทย)',
  `th_surname` varchar(100) DEFAULT NULL COMMENT 'นามสกุล (ไทย)',
  `dob` date DEFAULT NULL COMMENT 'วันเกิด (Date of Birth)',
  `nationality` int(11) DEFAULT NULL COMMENT 'รหัสสัญชาติ (เชื่อมกับตาราง nationality)',
  `address` text DEFAULT NULL COMMENT 'ที่อยู่',
  `email` varchar(100) DEFAULT NULL COMMENT 'อีเมลหลัก',
  `email2` varchar(100) DEFAULT NULL COMMENT 'อีเมลสำรอง',
  `tel` varchar(50) DEFAULT NULL COMMENT 'เบอร์โทรศัพท์',
  `position` varchar(255) DEFAULT NULL COMMENT 'ตำแหน่ง',
  `university` varchar(255) DEFAULT NULL COMMENT 'มหาวิทยาลัย',
  `faculty` varchar(255) DEFAULT NULL COMMENT 'คณะ',
  `department` varchar(255) DEFAULT NULL COMMENT 'ภาควิชา',
  `unit` varchar(255) DEFAULT NULL COMMENT 'หน่วยงาน',
  `mpd_status` tinyint(4) DEFAULT 1 COMMENT 'สถานะบุคลากร'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

