CREATE TABLE `program` (
  `program_id` int(11) NOT NULL,
  `p_name` varchar(255) DEFAULT NULL COMMENT 'ชื่อหลักสูตร (ภาษาอังกฤษ)',
  `p_thname` varchar(255) DEFAULT NULL COMMENT 'ชื่อหลักสูตร (ภาษาไทย)',
  `p_description` text DEFAULT NULL COMMENT 'คำอธิบายหลักสูตร',
  `p_sname` varchar(10) DEFAULT NULL COMMENT 'อักษรย่อหลักสูตร',
  `p_degree` varchar(100) DEFAULT NULL COMMENT 'ระดับปริญญา (e.g., M.Sc., Ph.D.)',
  `c_part` tinyint(4) DEFAULT NULL COMMENT 'สาขา: 1=Epi, 2=DSCI',
  `p_status` tinyint(4) DEFAULT 1 COMMENT 'สถานะหลักสูตร (1=Active)',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

