CREATE TABLE `proposal` (
  `proposal_id` int(11) NOT NULL,
  `std_id` int(11) NOT NULL COMMENT 'FK → student.std_id',
  `proposal_title` varchar(500) DEFAULT NULL COMMENT 'Proposal title',
  `major_advisor_id` int(11) DEFAULT NULL COMMENT 'FK → lecturer.lec_id (Major Advisor)',
  `approve_date` date DEFAULT NULL COMMENT 'Date topic approved',
  `proposal_status` enum('pre_defend','post_defend') DEFAULT NULL COMMENT 'Proposal workflow status: pre_defend = before defense, post_defend = after defense',
  `file_link` varchar(1000) DEFAULT NULL COMMENT 'URL link to completed/approved proposal document (e.g. Google Drive)',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Proposal main record per student';

