  `study_plan` tinyint(4) DEFAULT NULL COMMENT '1=Research only, 2=Coursework and research (Doctoral only)',
  `s_yearin` int(11) DEFAULT NULL COMMENT 'ปีการศึกษาที่เข้า (Year In)',
  `s_yearout` int(11) DEFAULT NULL COMMENT 'ปีการศึกษาที่จบ (Year Out)',
  `s_datein` date DEFAULT NULL COMMENT 'วันที่เริ่มศึกษา',
