  `s_specialty` varchar(255) DEFAULT NULL COMMENT 'ความเชี่ยวชาญ/หัวข้อสนใจ',
  `s_interest` varchar(255) DEFAULT NULL COMMENT 'สิ่งที่สนใจเป็นพิเศษ',
