  `is_transfer` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Transfer student flag (0=No, 1=Yes)',
  `transfer_from` varchar(20) DEFAULT NULL COMMENT 'Transfer from degree: M.Sc. or Ph.D.',
  `transfer_note` text DEFAULT NULL COMMENT 'Transfer additional details/notes',
  `is_drop` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Drop/Withdraw flag (0=No, 1=Yes)',
  `drop_note` text DEFAULT NULL COMMENT 'Drop reason / additional details'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

