-- --------------------------------------------------------

--
-- Table structure for table `student_meeting`
--

CREATE TABLE `student_meeting` (
  `mt_id` int(11) NOT NULL,
  `std_id` int(11) NOT NULL COMMENT 'Student reference',
  `mt_date` date DEFAULT NULL COMMENT 'Meeting date',
  `mt_status` tinyint(4) DEFAULT 1 COMMENT '1=Appoinment, 2=Postponed, 3=Cancelled by student, 4=Cancelled by advisor',
  `mt_topic` text DEFAULT NULL,
  `mt_detail` text DEFAULT NULL COMMENT 'Meeting detail (student fills)',
  `mt_note` text DEFAULT NULL COMMENT 'Scheduler/Admin note',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

