--
-- Table structure for table `student_tor`
--

CREATE TABLE `student_tor` (
  `tor_id` int(11) NOT NULL,
  `std_id` int(11) NOT NULL COMMENT 'Student reference',
  `tor_date` date DEFAULT NULL COMMENT 'Progress date',
  `academic_year` varchar(4) DEFAULT NULL,
  `tor_round` int(11) DEFAULT NULL COMMENT 'Progress round number',
  `tor_detail` text DEFAULT NULL COMMENT 'Detail',
  `tor_result` tinyint(4) DEFAULT NULL COMMENT '1=Pass, 2=Fail',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

