--
-- Table structure for table `thesis`
--

CREATE TABLE `thesis` (
  `thesis_id` int(11) NOT NULL,
  `std_id` int(11) NOT NULL COMMENT 'FK → student.std_id',
  `thesis_title` varchar(500) DEFAULT NULL COMMENT 'Thesis / Dissertation title',
  `major_advisor_id` int(11) DEFAULT NULL COMMENT 'FK → lecturer.lec_id (Major Advisor)',
  `cochair_id` int(11) DEFAULT NULL COMMENT 'FK → lecturer.lec_id (Co-chair 1 person)',
  `file_link` varchar(1000) DEFAULT NULL COMMENT 'URL link to completed final thesis document (e.g. Google Drive, repository)',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Thesis main record per student';

