--
-- Triggers `thesis_defend`
--
DELIMITER $$
CREATE TRIGGER `trg_thesis_defend_dates` BEFORE INSERT ON `thesis_defend` FOR EACH ROW BEGIN
  IF NEW.result = 'pass_no_condition' THEN
    SET NEW.final_thesis_due    = NULL;
    SET NEW.due_date_submission = DATE_ADD(NEW.defend_date, INTERVAL 21 DAY);
  ELSEIF NEW.result = 'pass_with_condition' AND NEW.condition_days IS NOT NULL THEN
    SET NEW.final_thesis_due    = DATE_ADD(NEW.defend_date, INTERVAL NEW.condition_days DAY);
    SET NEW.due_date_submission = DATE_ADD(NEW.final_thesis_due, INTERVAL 21 DAY);
  ELSE
    SET NEW.final_thesis_due    = NULL;
    SET NEW.due_date_submission = NULL;
  END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_thesis_defend_dates_update` BEFORE UPDATE ON `thesis_defend` FOR EACH ROW BEGIN
  IF NEW.result = 'pass_no_condition' THEN
    SET NEW.final_thesis_due    = NULL;
    SET NEW.due_date_submission = DATE_ADD(NEW.defend_date, INTERVAL 21 DAY);
  ELSEIF NEW.result = 'pass_with_condition' AND NEW.condition_days IS NOT NULL THEN
    SET NEW.final_thesis_due    = DATE_ADD(NEW.defend_date, INTERVAL NEW.condition_days DAY);
    SET NEW.due_date_submission = DATE_ADD(NEW.final_thesis_due, INTERVAL 21 DAY);
  ELSE
    SET NEW.final_thesis_due    = NULL;
    SET NEW.due_date_submission = NULL;
  END IF;
END
$$
DELIMITER ;

