--
-- Stand-in structure for view `v_user_consent_status`
-- (See below for the actual view)
--
CREATE TABLE `v_user_consent_status` (
`user_id` int(11)
,`username` varchar(255)
,`email` varchar(255)
,`user_type` enum('student','lecturer','educator','admin')
,`status` enum('pending','approved','rejected')
,`consent_given` tinyint(1)
,`privacy_ver` varchar(10)
,`consented_at` datetime
,`consent_ip` varchar(45)
);

-- --------------------------------------------------------

--
-- Structure for view `v_user_consent_status`
--
DROP TABLE IF EXISTS `v_user_consent_status`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_user_consent_status`  AS SELECT `u`.`id` AS `user_id`, `u`.`username` AS `username`, `u`.`email` AS `email`, `u`.`user_type` AS `user_type`, `u`.`status` AS `status`, `cl`.`consent_given` AS `consent_given`, `cl`.`privacy_ver` AS `privacy_ver`, `cl`.`consented_at` AS `consented_at`, `cl`.`ip_address` AS `consent_ip` FROM (`user` `u` left join (select `c1`.`id` AS `id`,`c1`.`user_id` AS `user_id`,`c1`.`consent_type` AS `consent_type`,`c1`.`consent_given` AS `consent_given`,`c1`.`privacy_ver` AS `privacy_ver`,`c1`.`ip_address` AS `ip_address`,`c1`.`user_agent` AS `user_agent`,`c1`.`consented_at` AS `consented_at` from (`consent_log` `c1` join (select `consent_log`.`user_id` AS `user_id`,max(`consent_log`.`consented_at`) AS `latest` from `consent_log` where `consent_log`.`consent_type` = 'registration' group by `consent_log`.`user_id`) `c2` on(`c1`.`user_id` = `c2`.`user_id` and `c1`.`consented_at` = `c2`.`latest`))) `cl` on(`u`.`id` = `cl`.`user_id`)) ;
COMMIT;

